import { parseFrontmatter } from '@mintlify/common';
import { getGeneratedRouteKey } from './docsConfig/generatedRouteCollisions.js';
export const createGeneratedGraphqlRouteIndex = (pagesAcc) => {
    const routes = new Map();
    for (const [slug, metadata] of Object.entries(pagesAcc)) {
        if (metadata.graphql != null) {
            const routeKey = getGeneratedRouteKey(slug);
            if (!routes.has(routeKey))
                routes.set(routeKey, slug);
        }
    }
    return routes;
};
/**
 * When user MDX doesn't explicitly set title/description, preserve the
 * auto-generated values (e.g. from OpenAPI schemas) that already exist
 * in pagesAcc. Mutates pageMetadata and pagesAcc in place.
 */
export const preserveAutoGeneratedMetadata = (contentStr, slug, pageMetadata, pagesAcc, graphqlRoutes = createGeneratedGraphqlRouteIndex(pagesAcc)) => {
    const routeKey = getGeneratedRouteKey(slug);
    const graphqlCollision = graphqlRoutes.get(routeKey);
    if (graphqlCollision !== undefined) {
        throw new Error(`User page route "${slug}" collides with generated GraphQL route "${graphqlCollision}"`);
    }
    const existing = pagesAcc[slug];
    if (existing) {
        try {
            const frontmatter = parseFrontmatter(contentStr).attributes;
            if (!frontmatter.title && existing.title)
                pageMetadata.title = existing.title;
            if (!frontmatter.description && existing.description)
                pageMetadata.description = existing.description;
            if (!frontmatter.sidebarTitle && existing.sidebarTitle)
                pageMetadata.sidebarTitle = existing.sidebarTitle;
        }
        catch { }
    }
    pagesAcc[slug] = pageMetadata;
    if (pageMetadata.graphql != null)
        graphqlRoutes.set(routeKey, slug);
};
